package com.mobility.demo.tracking;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.content.pm.ServiceInfo;
import android.location.*;
import android.os.*;
import org.json.JSONObject;
import java.io.*;
import java.net.*;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.*;

/** A bounded, driver-started location session. */
public final class TrackingService extends Service {
    private static final String CHANNEL="trip_tracking"; private static final int NOTIFY=9, MAX_RESPONSE=65536;
    private LocationManager locations; private long sequence,generation; private String server,trip,session,sessionKey; private TokenStore tokens; private QueueStore queue; private Handler handler; private final ExecutorService network=Executors.newSingleThreadExecutor(); private volatile boolean active;
    private final BroadcastReceiver connectivity=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){if(active)network.execute(()->{if(session!=null)flush();else openSession(generation);});}};
    @Override public void onCreate(){super.onCreate();tokens=new TokenStore(this);queue=new QueueStore(this);handler=new Handler(Looper.getMainLooper());createChannel();registerReceiver(connectivity,new IntentFilter("android.net.conn.CONNECTIVITY_CHANGE"));}
    @Override public int onStartCommand(Intent in,int flags,int id){
        if(in==null||"STOP".equals(in.getAction())){stopSharing();return START_NOT_STICKY;}
        String incomingServer=in.getStringExtra("server"),incomingTrip=in.getStringExtra("trip");if(incomingServer==null||incomingTrip==null){stopSelf();return START_NOT_STICKY;}
        if(active&&incomingServer.equals(server)&&incomingTrip.equals(trip))return START_NOT_STICKY;
        if(active)replaceActive(); server=incomingServer;trip=incomingTrip; queue.prepareContext(server,trip); generation++; active=true;session=null;sessionKey=UUID.randomUUID().toString();final long g=generation;Notification n=notification("Starting private trip sharing");if(Build.VERSION.SDK_INT>=29)startForeground(NOTIFY,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION);else startForeground(NOTIFY,n);if(!hasLocation()){stopSharing();return START_NOT_STICKY;}startLocation();network.execute(()->openSession(g));return START_NOT_STICKY;
    }
    private boolean hasLocation(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
    private void startLocation(){locations=(LocationManager)getSystemService(LOCATION_SERVICE);try{locations.requestLocationUpdates(LocationManager.GPS_PROVIDER,10000L,10f,listener,Looper.getMainLooper());locations.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,10000L,10f,listener,Looper.getMainLooper());}catch(SecurityException ignored){stopSharing();}}
    private final LocationListener listener=new LocationListener(){public void onLocationChanged(Location l){if(!active||l==null||session==null||!l.hasAccuracy()||l.getAccuracy()<=0||l.getAccuracy()>500)return;sequence++;queue.add(new QueueStore.LocationPayload(sequence,l.getLatitude(),l.getLongitude(),l.getAccuracy(),recordedAt(l.getTime())));flush();}};
    private static String recordedAt(long millis){SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",Locale.US);f.setTimeZone(TimeZone.getTimeZone("UTC"));return f.format(new Date(millis>0?millis:System.currentTimeMillis()));}
    private void openSession(long g){if(!active||g!=generation)return;final String base=server,tripId=trip,key=sessionKey;try{String t=tokens.get();if(t==null){reauth();return;}ApiResult r=post(base,"/api/mobility/trips/"+tripId+"/tracking/session",new JSONObject().put("consent",true).toString(),key,t);String ec=r.error();if(!active||g!=generation){if(r.code>=200&&r.code<300){String late=sessionId(r.body);if(late!=null)network.execute(()->safeStop(base,tripId,late,t));}return;}if(r.code==410||"TRACKING_UNAVAILABLE".equals(ec)){terminal();return;}if(r.code==401||r.code==403){reauth();return;}if("IDEMPOTENCY_CONFLICT".equals(ec)){reauth();return;}if(r.code>=200&&r.code<300){session=sessionId(r.body);if(session==null)throw new IOException("missing session_id");queue.bindSession(base,tripId,session);update("Sharing active");flush();}else retrySession(g);}catch(Exception e){if(active&&g==generation)retrySession(g);}}
    private static String sessionId(String body){try{JSONObject root=new JSONObject(body),data=root.optJSONObject("data");return data!=null?data.optString("session_id",null):root.optString("session_id",null);}catch(Exception ignored){return null;}}
    private void retrySession(long g){handler.postDelayed(()->{if(active&&g==generation)network.execute(()->openSession(g));},15000);}
    private void flush(){final String current=session,base=server,tripId=trip;final long g=generation;if(!active||current==null)return;network.execute(()->{try{String t=tokens.get();if(t==null){reauth();return;}for(QueueStore.LocationPayload p:queue.all()){if(!active||g!=generation||!current.equals(session))return;ApiResult r=post(base,"/api/mobility/trips/"+tripId+"/tracking/locations",p.body(current).toString(),p.key,t);if(!active||g!=generation)return;String ec=r.error();if(r.code==410||"TRACKING_UNAVAILABLE".equals(ec)){terminal();return;}if(r.code==401||r.code==403){reauth();return;}if("TRACKING_SESSION_STALE".equals(ec)){session=null;sessionKey=UUID.randomUUID().toString();openSession(g);return;}if("SEQUENCE_OUT_OF_ORDER".equals(ec)||"TIMESTAMP_OUT_OF_ORDER".equals(ec)||r.code==422){queue.remove(p.key);continue;}if("IDEMPOTENCY_CONFLICT".equals(ec)){reauth();return;}if(r.code>=200&&r.code<300)queue.remove(p.key);else{retryFlush(g,current);return;}}}catch(Exception e){try{tokens.get();}catch(Exception fatal){reauth();return;}retryFlush(g,current);}});}
    private void retryFlush(long g,String expected){handler.postDelayed(()->{if(active&&g==generation&&expected.equals(session))network.execute(this::flush);},15000);}
    private ApiResult post(String base,String path,String body,String idem,String token)throws Exception{URL u=new URL(base+path),origin=new URL(base);if(!u.getProtocol().equalsIgnoreCase(origin.getProtocol())||!u.getHost().equalsIgnoreCase(origin.getHost())||u.getPort()!=origin.getPort())throw new SecurityException("origin changed");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(7000);c.setRequestMethod("POST");c.setDoOutput(true);byte[] bytes=body.getBytes(java.nio.charset.StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(bytes.length);c.setRequestProperty("Accept","application/json");c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Idempotency-Key",idem);try(OutputStream o=c.getOutputStream()){o.write(bytes);}int code=c.getResponseCode();String out=readBounded(code>=400?c.getErrorStream():c.getInputStream());c.disconnect();return new ApiResult(code,out);}
    private static String readBounded(InputStream in)throws IOException{if(in==null)return"";ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[2048];int n,total=0;while((n=in.read(x))!=-1){total+=n;if(total>MAX_RESPONSE)throw new IOException("response too large");b.write(x,0,n);}return b.toString("UTF-8");}
    private void replaceActive(){generation++;active=false;handler.removeCallbacksAndMessages(null);try{if(locations!=null)locations.removeUpdates(listener);}catch(Exception ignored){}final String oldSession=session,oldServer=server,oldTrip=trip,oldToken;try{oldToken=tokens.get();}catch(Exception e){queue.clear();session=null;return;}queue.clear();session=null;if(oldSession!=null&&oldToken!=null&&oldServer!=null&&oldTrip!=null)network.execute(()->safeStop(oldServer,oldTrip,oldSession,oldToken));}
    private void stopSharing(){final long stopGeneration=++generation;active=false;handler.removeCallbacksAndMessages(null);try{if(locations!=null)locations.removeUpdates(listener);}catch(Exception ignored){}final String oldSession=session,oldServer=server,oldTrip=trip,oldToken;try{oldToken=tokens.get();}catch(Exception e){clearLocalSession();finishStopped();return;}queue.clear();session=null;clearLocalSession();if(oldSession!=null&&oldToken!=null&&oldServer!=null&&oldTrip!=null)network.execute(()->{safeStop(oldServer,oldTrip,oldSession,oldToken);handler.post(()->{if(generation==stopGeneration)finishStopped();});});else finishStopped();}
    private void safeStop(String base,String tripId,String oldSession,String token){try{postStop(base,tripId,oldSession,token);}catch(Exception ignored){}}
    private void postStop(String base,String tripId,String oldSession,String token)throws Exception{String body=new JSONObject().put("session_id",oldSession).toString();byte[] bytes=body.getBytes(java.nio.charset.StandardCharsets.UTF_8);ApiResult ignored=post(base,"/api/mobility/trips/"+tripId+"/tracking/stop",body,UUID.randomUUID().toString(),token);}
    private void finishStopped(){stopForeground(true);stopSelf();}
    private void terminal(){try{if(locations!=null)locations.removeUpdates(listener);}catch(Exception ignored){}active=false;handler.removeCallbacksAndMessages(null);queue.clear();session=null;clearLocalSession();update("Trip is terminal; sharing stopped");finishStopped();}
    private void reauth(){try{if(locations!=null)locations.removeUpdates(listener);}catch(Exception ignored){}active=false;handler.removeCallbacksAndMessages(null);queue.clear();session=null;tokens.clear();getSharedPreferences("private_tracking",0).edit().remove("server").remove("trip").apply();update("Session expired; start again");finishStopped();}
    private void clearLocalSession(){tokens.clear();getSharedPreferences("private_tracking",0).edit().remove("server").remove("trip").apply();}
    private void update(String text){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(NOTIFY,notification(text));}
    private Notification notification(String text){Intent stop=new Intent(this,TrackingService.class).setAction("STOP");PendingIntent pi=PendingIntent.getService(this,4,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_menu_mylocation).setContentTitle("Mobility trip sharing").setContentText(text).setOngoing(true).addAction(new Notification.Action.Builder(null,"Stop sharing",pi).build()).build();}
    private void createChannel(){if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel(CHANNEL,"Trip sharing",NotificationManager.IMPORTANCE_LOW));}
    @Override public void onDestroy(){active=false;handler.removeCallbacksAndMessages(null);try{unregisterReceiver(connectivity);}catch(Exception ignored){}try{if(locations!=null)locations.removeUpdates(listener);}catch(Exception ignored){}network.shutdownNow();super.onDestroy();}
    @Override public IBinder onBind(Intent i){return null;}
    private static final class ApiResult{final int code;final String body;ApiResult(int c,String b){code=c;body=b;}String error(){try{JSONObject root=new JSONObject(body),e=root.optJSONObject("error");return e==null?null:e.optString("code",null);}catch(Exception ignored){return null;}}}
}
